        public static HtmlString Render(string name, int size = 18)
        {
            if (!Paths.TryGetValue(name, out var paths))
            {
                throw new ArgumentException("Unknown dashboard icon.", nameof(name));
            }

            if (size is < 1 or > 128)
            {
                throw new ArgumentOutOfRangeException(nameof(size));
            }

            return new HtmlString($"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{size}\" height=\"{size}\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">{paths}</svg>");
        }
    }
